"""
Learning content: a glossary, a pool of daily tips and a few reading paths.

General education only: no recommendations, no predictions. Everything is written to be true as a
general principle (US-centric where it touches taxes or market rules). Tests check structure and
tone (unique ids, related terms exist, no hype words); the facts are reviewed by hand.

GLOSSARY entry: term, category, short (what it is), why (why it matters), optional example,
                optional app = (label, page path) where you can see it in this dashboard,
                related = [other terms].
TIP entry:      id, topic, text, optional term (a glossary term to read next), optional app path.
"""

from __future__ import annotations

CATEGORIES = ["Basics", "Risk", "Income", "Portfolio", "Strategy", "Market"]


def g(term, category, short, why, example=None, app=None, related=()):
    return {"term": term, "category": category, "short": short, "why": why, "example": example, "app": app, "related": list(related)}


